// Fase 5c (Adicionar módulos + Transferidor de dados; inclui a 5b) — PAINEL
// Uso: coloque este arquivo na pasta do projeto e rode:  node instalar-fase5c-painel.cjs
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const raiz = process.cwd();
if (!fs.existsSync(path.join(raiz, 'src', 'app')) || !fs.existsSync(path.join(raiz, 'bot-template'))) {
  console.error('❌ Rode dentro da pasta do PAINEL (onde ficam src/app e bot-template).');
  process.exit(1);
}
const arquivos = JSON.parse(zlib.gunzipSync(Buffer.from(DADOS(), 'base64')).toString('utf8'));
let n = 0;
for (const [rel, conteudo] of Object.entries(arquivos)) {
  const destino = path.join(raiz, ...rel.split('/'));
  fs.mkdirSync(path.dirname(destino), { recursive: true });
  const existia = fs.existsSync(destino);
  fs.writeFileSync(destino, conteudo);
  console.log((existia ? '  atualizado  ' : '  criado      ') + rel);
  n++;
}

// adiciona a tabela BuilderPrice no prisma/schema.prisma (só se ainda não tiver)
const schemaPath = path.join(raiz, 'prisma', 'schema.prisma');
if (fs.existsSync(schemaPath)) {
  const schema = fs.readFileSync(schemaPath, 'utf8');
  if (schema.includes('model BuilderPrice')) console.log('  já tinha    prisma/schema.prisma (BuilderPrice)');
  else {
    fs.writeFileSync(schemaPath, schema.replace(/\s*$/, '\n') + "\n// Preços do \"Monte o seu bot\" (editados em /admin/loja/montador).\n// Sem linha aqui = usa o preço padrão de src/lib/builder/catalog.ts no painel.\nmodel BuilderPrice {\n  moduleId   String   @id // \"base\" ou o id do módulo (ex.: \"moderacao\")\n  priceCents Int\n  active     Boolean  @default(true) // false = módulo fora de venda\n  updatedAt  DateTime @updatedAt\n}\n");
    console.log('  ajustado    prisma/schema.prisma (tabela BuilderPrice)');
  }
} else console.log('  ⚠️ não achei prisma/schema.prisma');
console.log('\n✅ ' + n + ' arquivo(s) prontos. Pode apagar o instalar-fase5c-painel.cjs.');
function DADOS() { return ''; }
